#include <iostream>
using namespace std;

using int64 = long long;

int64 countElements(int64 x) {
    return x / 8 + x / 27;
}

int64 kthElement(int64 k, int64 limit) {
    int64 left = 1, right = limit;
    while (left < right) {
        int64 mid = left + (right - left) / 2;
        if (countElements(mid) >= k)
            right = mid;
        else
            left = mid + 1;
    }
    return left;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int64 LIMIT = 1000000000000000LL;

    int64 m;
    cin >> m;

    if (m <= 0 || countElements(LIMIT) < m + 1) {
        cout << -1 << '\n';
        return 0;
    }

    int64 current = kthElement(m, LIMIT);
    int64 next = kthElement(m + 1, LIMIT);

    cout << (current == next ? -1 : current) << '\n';
    return 0;
}

